const FRONTEND_ORIGIN = "http://localhost:3000";

const FREE_EGG_COOLDOWN = 8 * 60 * 60 * 1000; // 8 horas

function cacheKey(path) {
  return new Request(`https://cache.flappypi/${path}`);
}

async function generateUniqueUsername(env, googleSub) {
  for (let i = 0; i < 5; i++) {
    const candidate = generateUsername(googleSub, i);

    const exists = await env.DB.prepare(
      "SELECT 1 FROM users WHERE user_name = ? LIMIT 1"
    )
      .bind(candidate)
      .first();

    if (!exists) {
      return candidate;
    }
  }

  // fallback extremo (muy improbable)
  return `user_${googleSub.slice(-8)}`;
}

function randomDigits(length = 10) {
  const array = new Uint32Array(length);
  crypto.getRandomValues(array);

  return Array.from(array, n => (n % 10)).join("");
}

function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": FRONTEND_ORIGIN,
    "Access-Control-Allow-Credentials": "true",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
  };
}

function generateUsername() {
  const prefix = "flappypi";
  const digits = randomDigits(10); // mínimo 10 números

  return `${prefix}_${digits}`;
}

/* =========================
   JWT HELPERS
========================= */
function base64url(input) {
  return btoa(input)
    .replace(/=/g, "")
    .replace(/\+/g, "-")
    .replace(/\//g, "_");
}

function base64urlDecode(input) {
  input = input.replace(/-/g, "+").replace(/_/g, "/");
  const pad = input.length % 4;
  if (pad) input += "=".repeat(4 - pad);
  return atob(input);
}

async function signJWT(payload, secret) {
  const header = { alg: "HS256", typ: "JWT" };

  const encHeader = base64url(JSON.stringify(header));
  const encPayload = base64url(JSON.stringify(payload));
  const data = `${encHeader}.${encPayload}`;

  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );

  const signature = await crypto.subtle.sign(
    "HMAC",
    key,
    new TextEncoder().encode(data)
  );

  return `${data}.${base64url(
    String.fromCharCode(...new Uint8Array(signature))
  )}`;
}

function decodeJWT(token) {
  const [, payload] = token.split(".");
  return JSON.parse(base64urlDecode(payload));
}

async function requireUser(request, env) {
  const cookie = request.headers.get("Cookie") || "";
  const token = cookie.match(/session=([^;]+)/)?.[1];

  if (!token) {
    return null;
  }

  let payload;
  try {
    payload = decodeJWT(token);
  } catch {
    return null;
  }

  if (payload.exp < Math.floor(Date.now() / 1000)) {
    return null;
  }

  const user = await env.DB.prepare(
    "SELECT id, email, user_name FROM users WHERE id = ?"
  )
    .bind(payload.sub)
    .first();

  return user || null;
}

/* =========================
   WORKER
========================= */
export default {
  async fetch(request, env) {
    try {
      const url = new URL(request.url);

    /* =========================
       CORS PREFLIGHT (OBLIGATORIO)
    ========================= */
    if (request.method === "OPTIONS") {
      return new Response(null, {
        status: 204,
        headers: corsHeaders(),
      });
    }

    /* =========================
       HEALTH
    ========================= */
    if (url.pathname === "/health") {
      return new Response("flappypi-auth OK");
    }

    /* =========================
       LOGIN GOOGLE
    ========================= */
    if (url.pathname === "/auth/login") {
      const google = new URL("https://accounts.google.com/o/oauth2/v2/auth");

      google.searchParams.set("client_id", env.CLIENT_ID);
      google.searchParams.set("redirect_uri", env.REDIRECT_URI);
      google.searchParams.set("response_type", "code");
      google.searchParams.set("scope", "openid email profile");
      google.searchParams.set("prompt", "select_account");

      return Response.redirect(google.toString(), 302);
    }

    if (url.pathname === "/eggs/claim-free" && request.method === "POST") {
    try{
      const user = await requireUser(request, env);
    
      if (!user) {
        return new Response("Unauthorized", {
          status: 401,
          headers: corsHeaders(),
        });
      }
    
      const now = Date.now();
    
      const row = await env.DB.prepare(`
        SELECT eggs, last_free_egg_at
        FROM users
        WHERE id = ?
      `)
      .bind(user.id)
      .first();
    
      const lastClaim = row?.last_free_egg_at || 0;
    
      if (now - lastClaim < FREE_EGG_COOLDOWN) {
        return new Response(
          JSON.stringify({
            ok: false,
            reason: "cooldown",
            next_claim_at: lastClaim + FREE_EGG_COOLDOWN
          }),
          {
            status: 429,
            headers: {
              ...corsHeaders(),
              "Content-Type": "application/json",
            },
          }
        );
      }
    
      // Operación atómica
      await env.DB.batch([
        // sumar huevo
        env.DB.prepare(`
          UPDATE users
          SET
            eggs = eggs + 1,
            last_free_egg_at = ?
          WHERE id = ?
        `).bind(now, user.id),
    
        // registrar reward
        env.DB.prepare(`
          INSERT INTO egg_rewards (
            id,
            user_id,
            source,
            eggs,
            created_at
          ) VALUES (?, ?, ?, ?, ?)
        `).bind(
          crypto.randomUUID(),
          user.id,
          "free_8h",
          1,
          now
        )
      ]);
    
      return new Response(
        JSON.stringify({
          ok: true,
          eggs: row.eggs + 1,
          next_claim_at: now + FREE_EGG_COOLDOWN
        }),
        {
          headers: {
            ...corsHeaders(),
            "Content-Type": "application/json",
          },
        }
      );
    } catch (err) {
      const errorInfo = {
        name: err?.name,
        message: err?.message,
        stack: err?.stack,
        cause: err?.cause,
      };
    
      console.error(
        "[/game/finish] ERROR DETALLADO:",
        JSON.stringify(errorInfo, null, 2)
      );
    
      return new Response(
        JSON.stringify({
          error: "finish_failed",
          message: err?.message || "Unknown error",
          code: err?.name || "UNEXPECTED_ERROR"
        }),
        {
          status: 500,
          headers: {
            ...corsHeaders(),
            "Content-Type": "application/json",
          },
        }
      );
    }
    }    

    /* =========================
       CALLBACK GOOGLE
    ========================= */
    if (url.pathname === "/auth/callback") {
      const code = url.searchParams.get("code");
      if (!code) return new Response("Missing code", { status: 400 });

      const tokenRes = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          code,
          client_id: env.CLIENT_ID,
          client_secret: env.CLIENT_SECRET,
          redirect_uri: env.REDIRECT_URI,
          grant_type: "authorization_code",
        }),
      });

      const token = await tokenRes.json();
      if (!token.access_token) {
        return new Response(JSON.stringify(token), { status: 500 });
      }

      const userRes = await fetch(
        "https://openidconnect.googleapis.com/v1/userinfo",
        {
          headers: {
            Authorization: `Bearer ${token.access_token}`,
          },
        }
      );

      const user = await userRes.json();
      if (!user.sub || !user.email) {
        return new Response("Invalid user", { status: 500 });
      }

      /* ---- guardar en D1 ---- */
      const generatedUsername = await generateUniqueUsername(env, user.sub);

      await env.DB.prepare(
        `
        INSERT INTO users (id, email, name, picture, user_name, created_at)
        VALUES (?, ?, ?, ?, ?, ?)
        ON CONFLICT(id) DO UPDATE SET
          email = excluded.email,
          name = excluded.name,
          picture = excluded.picture
        `
      )
        .bind(
          user.sub,
          user.email,
          user.name || null,
          user.picture || null,
          generatedUsername,
          Date.now()
        )
        .run();

      /* ---- crear JWT ---- */
      const jwt = await signJWT(
        {
          sub: user.sub,
          email: user.email,
          name: user.name,
          iat: Math.floor(Date.now() / 1000),
          exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 30,
        },
        env.JWT_SECRET
      );

      /* ---- cookie + redirect (CON CORS) ---- */
      return new Response(null, {
        status: 302,
        headers: {
          ...corsHeaders(),
          "Set-Cookie": `session=${jwt}; HttpOnly; SameSite=None; Secure; Path=/`,
          "Location": "http://localhost:3000",
        },
      });
    }

    /* =========================
       ME (SESSION) + CORS
    ========================= */
    if (url.pathname === "/me") {
      const cookie = request.headers.get("Cookie") || "";
      const token = cookie.match(/session=([^;]+)/)?.[1];
    
      if (!token) {
        return new Response("Unauthorized", {
          status: 401,
          headers: corsHeaders(),
        });
      }
    
      const payload = decodeJWT(token);
      if (payload.exp < Math.floor(Date.now() / 1000)) {
        return new Response("Token expired", {
          status: 401,
          headers: corsHeaders(),
        });
      }
    
      const user = await env.DB.prepare(`
        SELECT
          id,
          name,
          picture,
          eggs,
          last_free_egg_at,
          user_name,
          pi_wallet,
          twitter,
          COALESCE(max_score, 0) AS max_score,
          COALESCE(total_score, 0) AS total_score,
          created_at
        FROM users
        WHERE id = ?
      `)
      .bind(payload.sub)
      .first();
    
      if (!user) {
        return new Response("User not found", {
          status: 401,
          headers: corsHeaders(),
        });
      }
    
      const rankRow = await env.DB.prepare(`
        SELECT COUNT(*) + 1 AS rank
        FROM users
        WHERE
          COALESCE(total_score, 0) > ?
          OR (
            COALESCE(total_score, 0) = ?
            AND created_at < ?
          )
      `)
      .bind(
        user.total_score,
        user.total_score,
        user.created_at
      )
      .first();
    
      return new Response(JSON.stringify({
        id: user.id,
        name: user.name,
        eggs: user.eggs,
        last_free_egg_at: user.last_free_egg_at,
        user_name: user.user_name,
        pi_wallet: user.pi_wallet,
        twitter: user.twitter,
        picture: user.picture,
        max_score: user.max_score,
        total_score: user.total_score,
        rank_total: rankRow.rank
      }), {
        headers: {
          ...corsHeaders(),
          "Content-Type": "application/json"
        }
      });
    }    

    if (url.pathname === "/tops") {

      const key = cacheKey("tops");
      const cached = await caches.default.match(key);

      if (cached) return cached;

      const topBest = await env.DB.prepare(`
        SELECT name, user_name, max_score
        FROM users
        WHERE max_score > 0
        ORDER BY max_score DESC, created_at ASC
        LIMIT 3
      `).all();
    
      const topTotal = await env.DB.prepare(`
        SELECT name, user_name, total_score
        FROM users
        WHERE total_score > 0
        ORDER BY total_score DESC, created_at ASC
        LIMIT 3
      `).all();

      const response = new Response(JSON.stringify({
        best: topBest.results,
        total: topTotal.results
      }), {
        headers: {
          ...corsHeaders(),
          "Content-Type": "application/json"
        }
      });

      await caches.default.put(
        key,
        response.clone(),
        { expirationTtl: 30 }
      );
    
      return response;
    }    

    /* =========================
      PROFILE UPDATE
    ========================= */
    if (url.pathname === "/profile/update" && request.method === "POST") {
      const user = await requireUser(request, env);

      if (!user) {
        return new Response("Unauthorized", {
          status: 401,
          headers: corsHeaders(),
        });
      }

      let body;
      try {
        body = await request.json();
      } catch {
        return new Response("Invalid JSON", {
          status: 400,
          headers: corsHeaders(),
        });
      }

      const { name, wallet, twitter } = body;

      if (!name || !name.trim()) {
        return new Response("Name required", {
          status: 400,
          headers: corsHeaders(),
        });
      }

      // opcional: validación básica wallet
      if (wallet && wallet.length > 120) {
        return new Response("Invalid wallet", {
          status: 400,
          headers: corsHeaders(),
        });
      }

      let twitterClean = null;

      if (twitter) {
        twitterClean = twitter
          .replace(/^@/, "")   // elimina @ si lo ponen
          .trim();
      
        if (!/^[a-zA-Z0-9_]{1,15}$/.test(twitterClean)) {
          return new Response("Invalid Twitter username", {
            status: 400,
            headers: corsHeaders(),
          });
        }
      }

      await env.DB.prepare(`
        UPDATE users
        SET
          name = ?,
          pi_wallet = ?,
          twitter = ?
        WHERE id = ?
      `)
      .bind(
        name.trim(),
        wallet?.trim() || null,
        twitterClean,
        user.id
      )
      .run();

      return new Response(
        JSON.stringify({ ok: true }),
        {
          status: 200,
          headers: {
            ...corsHeaders(),
            "Content-Type": "application/json",
          },
        }
      );
    }

    if (url.pathname === "/game/revive" && request.method === "POST") {
      const user = await requireUser(request, env);
      if (!user) {
        return new Response("Unauthorized", {
          status: 401,
          headers: corsHeaders()
        });
      }
    
      let body;
      try {
        body = await request.json();
      } catch {
        return new Response("Invalid JSON", {
          status: 400,
          headers: corsHeaders()
        });
      }
    
      const { gameToken } = body;
      if (!gameToken) {
        return new Response("Missing game token", {
          status: 400,
          headers: corsHeaders()
        });
      }
    
      let payload;
      try {
        payload = decodeJWT(gameToken);
      } catch {
        return new Response("Invalid game token", {
          status: 401,
          headers: corsHeaders()
        });
      }
    
      // 🔐 Validaciones de seguridad mínimas
      if (payload.sub !== user.id || payload.type !== "game") {
        return new Response("Invalid game token", {
          status: 401,
          headers: corsHeaders()
        });
      }
    
      const { game_uid } = payload;
      if (!game_uid) {
        return new Response("Invalid game context", {
          status: 400,
          headers: corsHeaders()
        });
      }
    
      const eggsCost = 5;
    
      // 🔎 Obtener huevos actuales
      const dbUser = await env.DB.prepare(
        "SELECT eggs FROM users WHERE id = ?"
      ).bind(user.id).first();
    
      if (!dbUser || dbUser.eggs < eggsCost) {
        return new Response("Not enough eggs", {
          status: 400,
          headers: corsHeaders()
        });
      }
    
      // 🔁 Obtener revive count actual
      const reviveKey1 = cacheKey(`revive-count/${user.id}`);
      
      const reviveEntry = await caches.default.match(reviveKey1);
      const reviveCount = reviveEntry
        ? parseInt(await reviveEntry.text(), 10)
        : 0;
    
      const reviveNo = reviveCount + 1;
    
      // 🧠 Operación atómica: descuento + registro
      await env.DB.batch([
        // 🥚 Descontar huevos (protegido)
        env.DB.prepare(`
          UPDATE users
          SET eggs = eggs - ?
          WHERE id = ? AND eggs >= ?
        `).bind(eggsCost, user.id, eggsCost),
    
        // 🧾 Registrar revive (solo control / auditoría)
        env.DB.prepare(`
          INSERT INTO game_revives (
            id,
            game_uid,
            user_id,
            revive_no,
            eggs_used,
            created_at
          ) VALUES (?, ?, ?, ?, ?, ?)
        `).bind(
          crypto.randomUUID(),
          game_uid,
          user.id,
          reviveNo,
          eggsCost,
          Date.now()
        )
      ]);
    
      // 🔐 Actualizar contador de revives SOLO si todo salió bien
      const reviveKey = cacheKey(`revive-count/${user.id}`);

      await caches.default.put(
        reviveKey,
        new Response(String(reviveNo), {
          headers: { "Cache-Control": "max-age=86400" }
        })
      );
    
      return new Response(
        JSON.stringify({
          ok: true,
          revive_no: reviveNo,
          eggs_left: dbUser.eggs - eggsCost
        }),
        {
          status: 200,
          headers: {
            ...corsHeaders(),
            "Content-Type": "application/json"
          }
        }
      );
    }    

    /* =========================
      LOGOUT
    ========================= */
    if (url.pathname === "/logout") {
      return new Response(null, {
        status: 302,
        headers: {
          ...corsHeaders(),
          // borrar cookie
          "Set-Cookie": "session=; HttpOnly; SameSite=None; Path=/; Max-Age=0",
          // volver al frontend
          "Location": "http://localhost:3000"
        },
      });
    }

    if (url.pathname === "/game/finish" && request.method === "POST") {
    //try{
      const user = await requireUser(request, env);
    
      if (!user) {
        return new Response("Unauthorized", {
          status: 401,
          headers: corsHeaders(),
        });
      }

      let body;
      try {
        body = await request.json();
      } catch {
        return new Response("Invalid JSON", {
          status: 400,
          headers: corsHeaders(),
        });
      }
    
      const { score, jumps, positions, startedAt, gameToken } = body;
      const { nonce, game_uid } = decodeJWT(gameToken);
    
      const durationSec = (Date.now() - startedAt) / 1000;
      const MAX_SCORE_PER_SEC = 3;
      
      if (score > durationSec * MAX_SCORE_PER_SEC) {
        return new Response("Score/time anomaly", {
          status: 403,
          headers: corsHeaders(),
        });
      }

      if (!Number.isInteger(score) || score < 0) {
        return new Response("Invalid score", {
          status: 400,
          headers: corsHeaders(),
        });
      }
    
      if (!gameToken) {
        return new Response("Missing game token", {
          status: 401,
          headers: corsHeaders(),
        });
      }
    
      let payload;
      try {
        payload = decodeJWT(gameToken);
      } catch {
        return new Response("Invalid game token", {
          status: 401,
          headers: corsHeaders(),
        });
      }
    
      if (payload.type !== "game" || payload.sub !== user.id) {
        return new Response("Invalid game token", {
          status: 401,
          headers: corsHeaders(),
        });
      }
    
      // =============================
      // VALIDACIONES SOLO EN PRODUCCIÓN
      // =============================
      if (env.ENV !== "dev") {
        // validar juego activo
        const activeKey = cacheKey(`game-active/${user.id}`);
        const active = await caches.default.match(activeKey);
        if (!active || (await active.text()) !== payload.nonce) {
          return new Response("Not active game", {
            status: 401,
            headers: corsHeaders(),
          });
        }
    
        // validar nonce one-time
        const nonceKey = cacheKey(`game-nonce/${payload.nonce}`);
        const nonceEntry = await caches.default.match(nonceKey);

        if (!nonceEntry) {
          return new Response("Game already used", {
            status: 401,
            headers: corsHeaders(),
          });
        }
    
        // invalidar tokens
        await caches.default.delete(nonceKey);
        await caches.default.delete(`game-active:${user.id}`);
      }
    
      const lastGame = await env.DB.prepare(`
        SELECT id, score
        FROM games
        WHERE user_id = ?
          AND game_uid = ?
        ORDER BY created_at DESC
        LIMIT 1
      `)
      .bind(user.id, game_uid)
      .first();

      const lastScore = lastGame ? lastGame.score : 0;
      const deltaScore = score - lastScore;
      const parentId = lastGame ? lastGame.id : null;
      const isFirstInsert = !lastGame;

      if (lastGame && score < lastScore) {
        return new Response("Invalid score regression", {
          status: 400,
          headers: corsHeaders(),
        });
      }

      // =============================
      // GUARDAR RESULTADOS
      // =============================
      await env.DB.batch([
        env.DB.prepare(
          "INSERT INTO games (user_id, score, id_parent, created_at, game_uid) VALUES (?, ?, ?, ?, ?)"
        ).bind(user.id, score, parentId, Date.now(), game_uid),
    
        env.DB.prepare(
          `
          UPDATE users SET
            games_played = games_played + ?,
            total_score = total_score + ?,
            max_score = CASE
              WHEN ? > max_score THEN ?
              ELSE max_score
            END
          WHERE id = ?
          `
        ).bind(isFirstInsert ? 1 : 0, deltaScore, score, score, user.id),
      ]);
    
      return new Response(
        JSON.stringify({ ok: true }),
        {
          status: 200,
          headers: {
            ...corsHeaders(),
            "Content-Type": "application/json",
          },
        }
      );
    /*} catch (err) {
      const errorInfo = {
        name: err?.name,
        message: err?.message,
        stack: err?.stack,
        cause: err?.cause,
      };
    
      console.error(
        "[/game/finish] ERROR DETALLADO:",
        JSON.stringify(errorInfo, null, 2)
      );
    
      return new Response(
        JSON.stringify({
          error: "finish_failed",
          message: err?.message || "Unknown error",
          code: err?.name || "UNEXPECTED_ERROR"
        }),
        {
          status: 500,
          headers: {
            ...corsHeaders(),
            "Content-Type": "application/json",
          },
        }
      );
    }*/
    }    

    /* -------- GAME START -------- */
    if (url.pathname === "/game/start" && request.method === "POST") {
      const user = await requireUser(request, env);
    
      if (!user) {
        return new Response("Unauthorized", {
          status: 401,
          headers: corsHeaders(),
        });
      }
    
      const nonce = crypto.randomUUID();
      const gameUid = crypto.randomUUID();      // ID lógico del juego
    
      const gameToken = await signJWT(
        {
          sub: user.id,
          nonce,
          game_uid: gameUid, // 🎯 lo que nos interesa ahora
          type: "game",
          iat: Math.floor(Date.now() / 1000),
          exp: Math.floor(Date.now() / 1000) + 60 * 60 * 24, // 24h
        },
        env.JWT_SECRET
      );
    
      // 👉 Cache SOLO en producción
      if (env.ENV !== "dev") {
        try {
          const activeKey = cacheKey(`game-active/${user.id}`);

          await caches.default.put(
            activeKey,
            new Response(nonce, {
              headers: { "Cache-Control": "max-age=86400" }
            })
          );
    
          const nonceKey = cacheKey(`game-nonce/${nonce}`);

          await caches.default.put(
            nonceKey,
            new Response("valid", {
              headers: { "Cache-Control": "max-age=86400" }
            })
          );
        } catch (e) {
          console.warn("Cache not available:", e);
        }
      }
    
      await caches.default.put(
        cacheKey(`revive-count/${user.id}`),
        new Response("0", {
          headers: { "Cache-Control": "max-age=86400" }
        })
      );

      return new Response(
        JSON.stringify({ gameToken }),
        {
          status: 200,
          headers: {
            ...corsHeaders(),
            "Content-Type": "application/json",
          },
        }
      );
    }    

    return new Response("Not Found", { status: 404 });
  } catch (err) {
    // 🔥 EVITA CORS FANTASMA 🔥
    if (err instanceof Response) {
      return new Response(err.body, {
        status: err.status,
        headers: corsHeaders(),
      });
    }

    return new Response("Internal Server Error", {
      status: 500,
      headers: corsHeaders(),
    });
  }
},
};

